NODE_PATH=$(npm root -g) node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// 1. Verify flight FLD3D594 availability
const flight = db.prepare(\"SELECT * FROM flights WHERE flight_id='FLD3D594' AND source_skill='tau2Airline'\").get();
const dates = JSON.parse(flight.dates_json);
const dateInfo = dates['2026-09-10'];
console.log('Flight status:', dateInfo.status);
console.log('Economy price:', dateInfo.prices.economy);
console.log('Economy seats:', dateInfo.available_seats.economy);

// 2. Verify user
const user = db.prepare(\"SELECT * FROM users WHERE user_id='user_fa209a3f'\").get();
const paymentMethods = JSON.parse(user.payment_methods_json);
console.log('User:', user.name);
console.log('Membership:', user.loyalty_tier);
console.log('Payment cc_2402ef91:', JSON.stringify(paymentMethods.cc_2402ef91));

// 3. Check existing bookings to find a unique ID
const existingBookings = db.prepare(\"SELECT booking_id FROM flight_bookings WHERE source_skill='tau2Airline'\").all();
const existingIds = existingBookings.map(b => b.booking_id);
console.log('Existing booking count:', existingIds.length);

// Generate unique booking ID
let bookingId = 'HATHAT';
for (const candidate of ['HATHAT', 'HATHAU', 'HATHAV']) {
    if (!existingIds.includes(candidate)) {
        bookingId = candidate;
        break;
    }
}
console.log('New booking ID:', bookingId);
"

NODE_PATH=$(npm root -g) node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const bookingId = 'HATHAT';
const userId = 'user_fa209a3f';
const flightId = 'FLD3D594';
const date = '2026-09-10';
const cabin = 'economy';
const price = 129;
const totalAmount = 129;

// Build booking data
const flightsJson = JSON.stringify([{
    flight_id: flightId,
    flight_number: flightId,
    origin: 'LAX',
    destination: 'SFO',
    date: date,
    price: price
}]);

const passengersJson = JSON.stringify([{
    first_name: 'Maya',
    last_name: 'Chen',
    dob: '1992-04-17'
}]);

const paymentHistoryJson = JSON.stringify([{
    payment_id: 'cc_2402ef91',
    amount: totalAmount
}]);

const bookedAt = '2024-05-15T15:00:00';

// Insert booking
const insertStmt = db.prepare(
    'INSERT INTO flight_bookings (booking_id, user_id, origin, destination, flight_type, cabin_class, flights_json, passengers_json, payment_history_json, booked_at, total_baggages, nonfree_baggages, add_insurance, status, source_skill) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)'
);

insertStmt.run(
    bookingId, userId, 'LAX', 'SFO', 'one_way', cabin,
    flightsJson, passengersJson, paymentHistoryJson,
    bookedAt, 2, 0, 'no', 'confirmed', 'tau2Airline'
);

// Update flight seat availability
const flight = db.prepare(\"SELECT dates_json FROM flights WHERE flight_id=? AND source_skill='tau2Airline'\").get(flightId);
const dates = JSON.parse(flight.dates_json);
dates[date].available_seats.economy -= 1; // 1 passenger
db.prepare(\"UPDATE flights SET dates_json=? WHERE flight_id=? AND source_skill='tau2Airline'\").run(
    JSON.stringify(dates), flightId
);

console.log('Booking created successfully!');

// Verify
const booking = db.prepare('SELECT * FROM flight_bookings WHERE booking_id=?').get(bookingId);
console.log('\\nBooking confirmation:');
console.log(JSON.stringify({
    booking_id: booking.booking_id,
    user_id: booking.user_id,
    origin: booking.origin,
    destination: booking.destination,
    flight_type: booking.flight_type,
    cabin: booking.cabin_class,
    flights: JSON.parse(booking.flights_json),
    passengers: JSON.parse(booking.passengers_json),
    payment: JSON.parse(booking.payment_history_json),
    total_baggages: booking.total_baggages,
    nonfree_baggages: booking.nonfree_baggages,
    insurance: booking.add_insurance,
    status: booking.status
}, null, 2));
"
